CREATE TABLE meetings (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, location_id CHAR(36) NOT NULL, account_id CHAR(36) NOT NULL, device_id CHAR(36) NOT NULL, presenter VARCHAR(300) NOT NULL, status VARCHAR(20) NOT NULL, payload JSON NOT NULL, created_at DATETIME(6) NOT NULL, UNIQUE KEY(organization_id,id), INDEX(organization_id,location_id,created_at), FOREIGN KEY(organization_id,location_id) REFERENCES locations(organization_id,id), FOREIGN KEY(organization_id,account_id) REFERENCES accounts(organization_id,id), FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE usage_events (id CHAR(36) PRIMARY KEY, organization_id CHAR(36) NOT NULL, location_id CHAR(36) NOT NULL, account_id CHAR(36) NOT NULL, device_id CHAR(36) NOT NULL, meeting_id CHAR(36) NOT NULL, event_key VARCHAR(255) NOT NULL, event_type VARCHAR(40) NOT NULL, content_id CHAR(36) NULL, broadcast_id CHAR(36) NULL, occurred_at_utc DATETIME(6) NOT NULL, server_received_at DATETIME(6) NOT NULL, payload JSON NOT NULL, UNIQUE KEY(organization_id,event_key), INDEX(organization_id,location_id,occurred_at_utc), INDEX(organization_id,broadcast_id,event_type), INDEX(organization_id,content_id,event_type), FOREIGN KEY(organization_id,meeting_id) REFERENCES meetings(organization_id,id), FOREIGN KEY(organization_id,location_id) REFERENCES locations(organization_id,id), FOREIGN KEY(organization_id,account_id) REFERENCES accounts(organization_id,id), FOREIGN KEY(organization_id,device_id) REFERENCES devices(organization_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
